            ('解体費の相場はいくらですか？', '公的な相場を示した資料はありません。公開されている実例は200万〜400万円台（見積もりや支払い額）です。地中のガラやアスベストで追加費用が出た例があります。※ 面積や構造がそろっておらず、相場としては使えません。'),
