        blurb='初めての人の全体像',
        description='簡易宿所の許可を取るには何をすればよいか。許可とは何か、取るまでの流れ、客室に必要な広さ、自分の家で取れそうかのチェック、保健所・消防署・建築の窓口で聞くことを、初めての人向けにまとめました。',
